async def act(page):
    """
    Navigate to the Magento Admin Coupons report and request a coupons
    report for the date range 05/01/2021 -> 05/15/2023.

    Accessibility-first approach with conservative fallbacks.
    """
    # Navigate to the Coupons report page (relative path)
    await page.goto('/index.php/admin/report_sales_coupons/index/')
    await page.wait_for_load_state('networkidle')

    date_from = '05/01/2021'
    date_to = '05/15/2023'

    # Try to fill native textboxes exposed as From/To
    try:
        if await page.get_by_role('textbox', name='From').count() > 0:
            await page.get_by_role('textbox', name='From').first.fill(date_from)
    except Exception:
        pass

    try:
        if await page.get_by_role('textbox', name='To').count() > 0:
            await page.get_by_role('textbox', name='To').first.fill(date_to)
    except Exception:
        pass

    # If the named fields weren't present, look for a group with two textboxes
    try:
        if await page.get_by_role('textbox', name='From').count() == 0 or await page.get_by_role('textbox', name='To').count() == 0:
            groups = page.get_by_role('group')
            if await groups.count() > 0:
                gcount = await groups.count()
                for i in range(gcount):
                    grp = groups.nth(i)
                    try:
                        if await grp.get_by_role('textbox').count() >= 2:
                            # prefer named fields inside the group if present
                            if await grp.get_by_role('textbox', name='From').count() > 0:
                                await grp.get_by_role('textbox', name='From').first.fill(date_from)
                            else:
                                await grp.get_by_role('textbox').nth(0).fill(date_from)
                            if await grp.get_by_role('textbox', name='To').count() > 0:
                                await grp.get_by_role('textbox', name='To').first.fill(date_to)
                            else:
                                await grp.get_by_role('textbox').nth(1).fill(date_to)
                            break
                    except Exception:
                        # if this group isn't suitable, continue scanning
                        continue
    except Exception:
        pass

    # As a last defensive fallback, fill the first two textboxes on the page if they are empty
    try:
        all_textboxes = page.get_by_role('textbox')
        if await all_textboxes.count() >= 2:
            try:
                v0 = (await all_textboxes.nth(0).input_value()).strip()
            except Exception:
                v0 = ''
            try:
                v1 = (await all_textboxes.nth(1).input_value()).strip()
            except Exception:
                v1 = ''
            if not v0:
                await all_textboxes.nth(0).fill(date_from)
            if not v1:
                await all_textboxes.nth(1).fill(date_to)
    except Exception:
        pass

    # Trigger the report generation. Prefer explicit 'Show Report' then 'Refresh'.
    try:
        if await page.get_by_role('button', name='Show Report').count() > 0:
            await page.get_by_role('button', name='Show Report').first.click()
            await page.wait_for_load_state('networkidle')
            return
    except Exception:
        pass

    try:
        if await page.get_by_role('button', name='Refresh').count() > 0:
            await page.get_by_role('button', name='Refresh').first.click()
            await page.wait_for_load_state('networkidle')
            return
    except Exception:
        pass

    # Final fallback: click the first button whose visible text contains action keywords
    try:
        buttons = page.get_by_role('button')
        if await buttons.count() > 0:
            bcount = await buttons.count()
            for i in range(bcount):
                b = buttons.nth(i)
                try:
                    txt = (await b.inner_text()).strip()
                except Exception:
                    txt = ''
                if any(k in txt.lower() for k in ('show', 'report', 'refresh', 'apply', 'filter')):
                    await b.click()
                    # assume click may navigate; stop further interactions
                    try:
                        await page.wait_for_load_state('networkidle')
                    except Exception:
                        await page.wait_for_timeout(2000)
                    return
    except Exception:
        pass

    # If nothing navigated, allow a brief moment for the report to render
    await page.wait_for_timeout(2000)

